const observeDeliverySystemAssignment = `-- name: ObserveDeliverySystemAssignment :one
WITH seeded AS (
    INSERT INTO delivery_system_cluster_assignments (
        cluster_id, desired_release_id, generation, phase, released_at
    )
    SELECT $1, r.id, r.release_sequence, 'released', now()
    FROM delivery_system_releases r
    WHERE r.state = 'released'
    ON CONFLICT (cluster_id) DO NOTHING
), current AS (
    SELECT a.cluster_id, a.phase
    FROM delivery_system_cluster_assignments a
    WHERE a.cluster_id = $1
    FOR UPDATE
), updated AS (
    UPDATE delivery_system_cluster_assignments a
    SET observed_distribution_digest = $2::text,
        observed_agent_version = $3::text,
        last_observed_at = $4,
        acknowledged_at = COALESCE(acknowledged_at, $4),
        phase = CASE
            WHEN $5::boolean
             AND $2::text = r.distribution_digest
             AND $3::text = r.agent_version
             AND a.phase IN ('rolling_back','rolled_back') THEN 'rolled_back'
            WHEN $5::boolean
             AND $2::text = r.distribution_digest
             AND $3::text = r.agent_version THEN 'ready'
            WHEN $6::text = 'incompatible'
             AND a.phase IN ('rolling_back','rolled_back') THEN 'rollback_failed'
            WHEN $6::text = 'incompatible' THEN 'failed'
            WHEN a.phase = 'rolled_back' THEN a.phase
            ELSE 'applying'
        END,
        ready_at = CASE
            WHEN $5::boolean
             AND $2::text = r.distribution_digest
             AND $3::text = r.agent_version
            THEN COALESCE(ready_at, $4) ELSE NULL END,
        last_error_code = CASE
            WHEN $5::boolean
             AND $2::text = r.distribution_digest
             AND $3::text = r.agent_version THEN ''
            ELSE $7::text END
    FROM delivery_system_releases r
    WHERE a.cluster_id = $1 AND r.id = a.desired_release_id
    RETURNING a.cluster_id, a.desired_release_id, a.previous_release_id, a.rollout_id, a.generation, a.cohort, a.release_order, a.phase, a.fence, a.released_at, a.acknowledged_at, a.ready_at, a.deadline, a.observed_distribution_digest, a.observed_agent_version, a.last_error_code, a.last_observed_at, a.created_at, a.updated_at
)
SELECT updated.cluster_id, updated.desired_release_id, updated.previous_release_id, updated.rollout_id, updated.generation, updated.cohort, updated.release_order, updated.phase, updated.fence, updated.released_at, updated.acknowledged_at, updated.ready_at, updated.deadline, updated.observed_distribution_digest, updated.observed_agent_version, updated.last_error_code, updated.last_observed_at, updated.created_at, updated.updated_at, current.phase AS previous_phase
FROM updated JOIN current USING (cluster_id)
`

type ObserveDeliverySystemAssignmentParams struct {
	ClusterID                  uuid.UUID          `json:"cluster_id"`
	ObservedDistributionDigest string             `json:"observed_distribution_digest"`
	ObservedAgentVersion       string             `json:"observed_agent_version"`
	ObservedAt                 pgtype.Timestamptz `json:"observed_at"`
	InventoryReady             bool               `json:"inventory_ready"`
	CompatibilityStatus        string             `json:"compatibility_status"`
	ErrorCode                  string             `json:"error_code"`
}

type ObserveDeliverySystemAssignmentRow struct {
	ClusterID                  uuid.UUID          `json:"cluster_id"`
	DesiredReleaseID           uuid.UUID          `json:"desired_release_id"`
	PreviousReleaseID          pgtype.UUID        `json:"previous_release_id"`
	RolloutID                  pgtype.UUID        `json:"rollout_id"`
	Generation                 int64              `json:"generation"`
	Cohort                     int32              `json:"cohort"`
	ReleaseOrder               int32              `json:"release_order"`
	Phase                      string             `json:"phase"`
	Fence                      int64              `json:"fence"`
	ReleasedAt                 pgtype.Timestamptz `json:"released_at"`
	AcknowledgedAt             pgtype.Timestamptz `json:"acknowledged_at"`
	ReadyAt                    pgtype.Timestamptz `json:"ready_at"`
	Deadline                   pgtype.Timestamptz `json:"deadline"`
	ObservedDistributionDigest string             `json:"observed_distribution_digest"`
	ObservedAgentVersion       string             `json:"observed_agent_version"`
	LastErrorCode              string             `json:"last_error_code"`
	LastObservedAt             pgtype.Timestamptz `json:"last_observed_at"`
	CreatedAt                  time.Time          `json:"created_at"`
	UpdatedAt                  time.Time          `json:"updated_at"`
	PreviousPhase              string             `json:"previous_phase"`
}

func (q *Queries) ObserveDeliverySystemAssignment(ctx context.Context, arg ObserveDeliverySystemAssignmentParams) (ObserveDeliverySystemAssignmentRow, error) {
	row := q.db.QueryRow(ctx, observeDeliverySystemAssignment,
		arg.ClusterID,
		arg.ObservedDistributionDigest,
		arg.ObservedAgentVersion,
		arg.ObservedAt,
		arg.InventoryReady,
		arg.CompatibilityStatus,
		arg.ErrorCode,
	)
	var i ObserveDeliverySystemAssignmentRow
	err := row.Scan(
		&i.ClusterID,
		&i.DesiredReleaseID,
		&i.PreviousReleaseID,
		&i.RolloutID,
		&i.Generation,
		&i.Cohort,
		&i.ReleaseOrder,
		&i.Phase,
		&i.Fence,
		&i.ReleasedAt,
		&i.AcknowledgedAt,
		&i.ReadyAt,
		&i.Deadline,
		&i.ObservedDistributionDigest,
		&i.ObservedAgentVersion,
		&i.LastErrorCode,
		&i.LastObservedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.PreviousPhase,
	)
	return i, err
}

const releaseDeliverySystemCohort = `-- name: ReleaseDeliverySystemCohort :many
UPDATE delivery_system_cluster_assignments
SET phase = 'released', released_at = now(), fence = fence + 1
WHERE rollout_id = $1
  AND cohort = $2
  AND phase = 'pending'
RETURNING cluster_id, desired_release_id, previous_release_id, rollout_id, generation, cohort, release_order, phase, fence, released_at, acknowledged_at, ready_at, deadline, observed_distribution_digest, observed_agent_version, last_error_code, last_observed_at, created_at, updated_at
`

type ReleaseDeliverySystemCohortParams struct {
	RolloutID pgtype.UUID `json:"rollout_id"`
	Cohort    int32       `json:"cohort"`
}

func (q *Queries) ReleaseDeliverySystemCohort(ctx context.Context, arg ReleaseDeliverySystemCohortParams) ([]DeliverySystemClusterAssignment, error) {
	rows, err := q.db.Query(ctx, releaseDeliverySystemCohort, arg.RolloutID, arg.Cohort)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DeliverySystemClusterAssignment{}
	for rows.Next() {
		var i DeliverySystemClusterAssignment
		if err := rows.Scan(
			&i.ClusterID,
			&i.DesiredReleaseID,
			&i.PreviousReleaseID,
			&i.RolloutID,
			&i.Generation,
			&i.Cohort,
			&i.ReleaseOrder,
			&i.Phase,
			&i.Fence,
			&i.ReleasedAt,
			&i.AcknowledgedAt,
			&i.ReadyAt,
			&i.Deadline,
			&i.ObservedDistributionDigest,
			&i.ObservedAgentVersion,
			&i.LastErrorCode,
			&i.LastObservedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const retireCurrentDeliverySystemRelease = `-- name: RetireCurrentDeliverySystemRelease :execrows
UPDATE delivery_system_releases
SET state = 'retired', retired_at = now()
WHERE state = 'released' AND id <> $1
`

func (q *Queries) RetireCurrentDeliverySystemRelease(ctx context.Context, nextReleaseID uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, retireCurrentDeliverySystemRelease, nextReleaseID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
